lib_rs:
//! Reference solution — `aggregate`, FAN API (`lgwks_bot::script::FanOut`).
//!
//! One call: bounded, fail-fast, drop-safe, with the failing id coming back as
//! the body's own error. No scope, no tenant, no shared cell.

use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::script::{FanOut, FanOutError};

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(ids: Vec<u32>, fetch: Fetcher, deadline: Duration) -> Result<u64, SolveError> {
    FanOut::new(ids)
        .at_most(4)
        .within(deadline)
        .run(|id| {
            let fetch = fetch.clone();
            async move { fetch.fetch(id).await.map_err(|error| error.id()) }
        })
        .await
        .map(|values| values.into_iter().sum())
        .map_err(|error| match error {
            FanOutError::Item { error: id, .. } => SolveError::Fetch { id },
            FanOutError::TimedOut { .. } => SolveError::Deadline,
            _ => SolveError::Cancelled,
        })
}

//! Reference solution — `capture`, FAN API (`FanOut` + supervised run).
//!
//! The fan-out surface owns the deadline where the `new` reference hands it
//! to the spec: one item, at most one at a time, within the task's deadline.
//! A `TimedOut` fan-out is the task's `Deadline`, and the supervisor still
//! owns the tree underneath it.

use std::num::NonZeroUsize;
use std::time::Duration;

/// Re-exported vocabulary so the oracle's `ai_trial::CaptureError` resolves.
pub use ai_task_support::capture::CaptureError;
/// Re-exported vocabulary so the oracle's `ai_trial::CaptureResult` resolves.
pub use ai_task_support::capture::CaptureResult;
use lgwks_bot::rt::process::{ProcessRunError, ProcessSpec};
use lgwks_bot::rt::supervise::Supervisor;
use lgwks_bot::script::{FanOut, FanOutError};

pub async fn solve(
    argv: Vec<String>,
    head_limit: usize,
    deadline: Duration,
) -> Result<CaptureResult, CaptureError> {
    let mut words = argv.into_iter();
    let binary = words.next().ok_or_else(|| CaptureError::Spawn("empty argv".to_owned()))?;
    let ceiling = NonZeroUsize::new(head_limit)
        .ok_or_else(|| CaptureError::Spawn("head_limit is zero".to_owned()))?;
    let rest: Vec<String> = words.collect();
    // One item: the deadline belongs to the fan-out, not the spec, so a slow
    // child is stopped by the surface that bounded it.
    let runs = FanOut::new([rest])
        .at_most(1)
        .within(deadline)
        .run(|args| {
            let binary = binary.clone();
            async move {
                let mut detail = ProcessSpec::new(binary);
                for arg in args {
                    detail.arg(arg);
                }
                detail.capture_stdout(ceiling);
                detail.capture_stderr(ceiling);
                let mut owned = Supervisor::new(1);
                owned.run_process(&detail).await.map_err(|failure| match failure {
                    ProcessRunError::NotStarted { source } => source.to_string(),
                    _ => "the supervisor stopped before the run settled".to_owned(),
                })
            }
        })
        .await
        .map_err(|failure| match failure {
            FanOutError::TimedOut { .. } => CaptureError::Deadline,
            FanOutError::Item { error, .. } => CaptureError::Spawn(error),
            _ => CaptureError::Cancelled,
        })?;
    let run = runs.into_iter().next().ok_or(CaptureError::Cancelled)?;
    if run.deadline_fired() {
        ai_task_support::diagnostic(format_args!("capture fan arm: the run outlived its deadline"));
        Err(CaptureError::Deadline)
    } else {
        let kept = run.stdout();
        Ok(CaptureResult::new(
            kept.bytes().to_vec(),
            kept.total_bytes(),
            kept.truncated(),
        ))
    }
}

//! Reference solution — `durable-retry`, FAN API (record + bounded `retry`).
//!
//! The same record discipline as the `new` arm: the file is the idempotency
//! key, read before anything is appended. The wait differs in how it is
//! bounded — attempts derived from the task's own deadline plus margin, so a
//! short deadline means a short wait rather than a fixed hundred thousand
//! polls, and exhaustion reads as the deadline it was derived from.

use std::path::PathBuf;
use std::time::Duration;

use ai_task_support::durable::{append_application, has_application, is_released};
use lgwks_bot::script::{FlowError, Scope, Tenant, attempts, retry};

pub use ai_task_support::durable::RecoverError; // fan arm

pub async fn solve(
    base: PathBuf,
    ticket: String,
    cap: Duration,
) -> Result<String, RecoverError> {
    std::fs::create_dir_all(&base).map_err(|error| {
        ai_task_support::diagnostic(format_args!("durable-retry fan arm: create_dir_all failed: {error:?}"));
        RecoverError::Deadline
    })?;
    // A line already there means an earlier attempt applied and died before
    // answering: reconcile instead of duplicating.
    let applied_before = has_application(&base, &ticket).map_err(|error| {
        ai_task_support::diagnostic(format_args!("durable-retry fan arm: record read failed: {error:?}"));
        RecoverError::Deadline
    })?;
    if !applied_before {
        append_application(&base, &ticket).map_err(|error| {
            ai_task_support::diagnostic(format_args!("durable-retry fan arm: append failed: {error:?}"));
            RecoverError::Deadline
        })?;
    }
    let outcome = if applied_before {
        format!("recovered:{ticket}")
    } else {
        format!("applied:{ticket}")
    };
    let scope = Scope::root(Tenant::new("durable").map_err(|error| {
        ai_task_support::diagnostic(format_args!("durable-retry fan arm: tenant refused: {error:?}"));
        RecoverError::Deadline
    })?);
    let opened = std::time::Instant::now();
    // Attempts cover the deadline at a hundred milliseconds apart, capped at
    // the thousand the bound allows: the elapsed check below enforces the
    // task's deadline, so exhaustion past the cap still reads as the
    // deadline it was derived from.
    let polls = u32::try_from(cap.as_millis() / 100 + 100)
        .map(|over| over.min(1000))
        .map_err(|error| {
            ai_task_support::diagnostic(format_args!("durable-retry fan arm: poll count overflowed: {error:?}"));
            RecoverError::Deadline
        })?;
    retry(
        &scope,
        "await-release",
        attempts(polls).map_err(|error| {
            ai_task_support::diagnostic(format_args!("durable-retry fan arm: poll bound refused: {error:?}"));
            RecoverError::Deadline
        })?,
        Duration::from_millis(100),
        |_, _| {
            let base = base.clone();
            async move {
                if is_released(&base) {
                    Ok(())
                } else if opened.elapsed() < cap {
                    Err(FlowError::transient("release not present yet"))
                } else {
                    Err(FlowError::failed("deadline"))
                }
            }
        },
    )
    .await
    .map_err(|error| {
        ai_task_support::diagnostic(format_args!("durable-retry fan arm: the wait was refused: {error:?}"));
        RecoverError::Deadline
    })?;
    Ok(outcome)
}

//! Reference solution — `pipeline`, FAN API (`lgwks_bot::script::FanOut`).
//!
//! `FanOut` runs `fetch_a` and `fetch_b` together and hands back the failing
//! stage's name as the body's own error; `timeout` carries the deadline and
//! drops the running work when it expires.

use std::time::Duration;

use ai_task_support::{Published, Stage, StageError, StageName};
use lgwks_bot::rt::time;
use lgwks_bot::script::{FanOut, FanOutError};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

/// The stage a failed run names. `StageError` has one shape; matching it keeps the
/// error read rather than discarded.
fn failed_stage(error: StageError) -> StageName {
    match error {
        StageError::Stage { name } => name,
    }
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let pipeline = async {
        FanOut::new([StageName::FetchA, StageName::FetchB])
            .at_most(2)
            .run(|name| {
                let stage = stage.clone();
                async move { stage.run(name).await.map_err(failed_stage) }
            })
            .await
            .map_err(|error| match error {
                FanOutError::Item { error: name, .. } => PipelineError::Stage { name },
                _ => PipelineError::Cancelled,
            })?;
        stage
            .run(StageName::Combine)
            .await
            .map_err(|error| PipelineError::Stage { name: failed_stage(error) })?;
        let artifact = stage
            .run(StageName::Publish)
            .await
            .map_err(|error| PipelineError::Stage { name: failed_stage(error) })?;
        Ok(Published::from(artifact))
    };
    match time::timeout(deadline, pipeline).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

//! Reference solution — `recovery` (NEW API: `lgwks_bot::task` + `script`).
//!
//! There is no OLD-API arm for this task, and the reason is architectural
//! rather than a gap in the harness: the old `lgwks_bot::rt` surface has no
//! durable run store, no `remember`, no run identity and no resume. Nothing in
//! it can express "finish the work without redoing a completed unit", because
//! it keeps no record of a completed unit to consult. A hand-rolled file
//! standing in for that store would measure the fixture the model wrote rather
//! than the crate.
//!
//! Four things have to be right, and this file shows each:
//!
//! 1. **A run identity that is stable across attempts.** [`RunId::from_hex`] over
//!    a digest of the tenant, so every attempt derives the same run and a second
//!    call finds the first call's records. A freshly minted identity per call
//!    would derive a *different* run every time and the resume would find
//!    nothing — the plausible first mistake this task exists to catch.
//! 2. **A durable store installed on the host**, so `remember` has somewhere to
//!    land and `Host::resume` has records to replay.
//! 3. **A helper that builds the task body once**, reused by both attempts. The
//!    step key is derived from the step *path*, so two attempts that spelled the
//!    step differently would record under different keys and never replay.
//! 4. **The effect applied once**, by reading [`Ledger::applied`] before applying.
//!
//! The interruption itself is the harness's business. This code never learns that
//! a first attempt was killed — it is simply correct when `recover` is called
//! again.

use std::path::PathBuf;
use std::sync::{Arc, Mutex, MutexGuard};
use std::time::Duration;

use ai_task_support::recovery::{Ledger, UnitError, World};
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{FlowError, Scope};
use lgwks_bot::task::{Disposition, Host, task};

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

/// The caller's refusal when the store cannot be had, naming why on stderr.
fn no_store(cause: impl std::fmt::Debug) -> RecoveryError {
    ai_task_support::diagnostic(format_args!("the recovery store was refused: {cause:?}"));
    RecoveryError::NoStore
}

/// Locks `mutex`, recovering from poisoning.
///
/// The guarded value is an `Option<u32>` that is only ever written as a whole
/// `Some(index)` or left alone, so a panic elsewhere cannot leave it
/// half-written: poisoning records that some thread unwound while holding the
/// guard, not that the recorded unit is unreadable. Taking the poisoned guard's
/// value keeps the unit the run actually failed at, which is the index the
/// caller is told.
fn lock<T>(mutex: &Mutex<T>) -> MutexGuard<'_, T> {
    match mutex.lock() {
        Ok(guard) => guard,
        Err(poisoned) => poisoned.into_inner(),
    }
}

/// The tenant every recovered run is booked under.
const TENANT: &str = "recovery";

/// The effect name the ledger is asked to apply exactly once.
const EFFECT: &str = "recover";

/// The run identity, derived rather than minted.
///
/// `RunId::mint` needs the estate's entropy source, and a fresh value would be
/// exactly wrong here: a second attempt has to derive the *same* run to find the
/// first attempt's records. So the identity is a digest of the tenant alone,
/// spelled out as a constant rather than recomputed at each call — which also
/// means this file carries no hashing for a solution to get subtly wrong.
const RUN: &str = "0f9d3a17c25b4e806b1de4372f5a9c60";

/// The body every unit runs under.
///
/// `World::unit` enters its own child scope per index, and a scope's key is its
/// *path*, so each unit is already independently keyed. This name is the parent
/// both attempts share, which is what makes the replay find what the first
/// attempt wrote.
const STEP: &str = "units";

/// Which unit failed, read back out of the body's own record.
///
/// Kept beside the failure rather than inside the error type: a task body returns
/// `FlowError`, so the unit index has to travel out-of-band for `recover` to name
/// it in `RecoveryError::Unit { index }`.
type Failed = Arc<Mutex<Option<u32>>>;

/// The future a task body returns, named once so both the task's type parameter
/// and the body that builds it are spelled against the same type.
type Body = std::pin::Pin<Box<dyn std::future::Future<Output = Result<u64, FlowError>>>>;

/// The helper: the one task body both attempts run.
///
/// Built by a function rather than written twice, because "the same task on both
/// attempts" is a property of this function returning the same task. Two
/// hand-written bodies that happen to agree today are two bodies that can drift
/// tomorrow, and that drift would show up as a solution that mysteriously fails
/// to replay rather than as a compile error.
fn recovery_task(
    world: World,
    failed: Failed,
) -> Result<lgwks_bot::task::Task<impl Fn(Scope, u32) -> Body>, RecoveryError> {
    let width = world.width();
    task(STEP, move |scope: Scope, _attempt: u32| -> Body {
        let world = world.clone();
        let failed = Arc::clone(&failed);
        Box::pin(async move {
            let mut total: u64 = 0;
            for index in 0..width {
                let value = world
                    .unit(&scope, index)
                    .await
                    .map_err(|UnitError::Unit { index }| {
                        *lock(&failed) = Some(index);
                        FlowError::failed(format!("unit {index} failed"))
                    })?;
                total = total.saturating_add(value);
            }
            // The exactly-once half. Read the ledger before applying: a replayed
            // run finds the effect already applied and skips it, so the count
            // stays at one across any number of attempts.
            let ledger: Ledger = world.ledger().clone();
            if !ledger.applied(EFFECT) {
                ledger.apply(EFFECT);
            }
            Ok(total)
        })
    })
    .map_err(no_store)
}

/// A host over `store_dir` for `TENANT`, carrying `deadline`.
///
/// One function so both attempts build the same host over the same directory:
/// the store is opened — and its existing records replayed — at
/// [`HostBuilder::run_store`](lgwks_bot::task::HostBuilder::run_store), so the
/// second attempt is the one that finds the first attempt's records.
fn recovery_host(store_dir: &std::path::Path, deadline: Duration) -> Result<Host, RecoveryError> {
    Host::builder(TENANT)
        .map_err(no_store)?
        .default_deadline(deadline)
        .run_store(store_dir)
        .map_err(no_store)?
        .build()
        .map_err(no_store)
}

/// Read the outcome of one attempt into the caller's own error type.
fn into_result(report: &lgwks_bot::task::Report<u64>, failed: &Failed) -> Result<u64, RecoveryError> {
    match report.disposition() {
        Disposition::Succeeded => report
            .output()
            .copied()
            .ok_or(RecoveryError::NoLedger),
        Disposition::DeadlineExceeded => Err(RecoveryError::Deadline),
        _ => {
            let index = lock(&failed);
            Err(match *index {
                Some(index) => RecoveryError::Unit { index },
                None => RecoveryError::NoStore,
            })
        }
    }
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let run = RunId::from_hex(RUN).map_err(no_store)?;
    let host = recovery_host(&store_dir, deadline)?;
    let failed: Failed = Arc::new(Mutex::new(None));
    // The world moves into the task: the caller reads the ledger from the world
    // it already holds, so this frame keeps no clone of its own.
    let work = recovery_task(world, Arc::clone(&failed))?;

    // The first attempt. Whatever it reaches, its records are already on the disk
    // by the time `remember` returned, so the resume below can find them.
    let first = host.run(&work, 0u32).await;
    let settled = into_result(&first, &failed);
    if settled.is_ok() {
        return settled;
    }

    // The second attempt, under the same derived run: every unit the first
    // attempt recorded replays without its body running again, and the units it
    // did not reach run now. The task, the scope and the run identity are the
    // same on both attempts, which is the whole reason this compiles into a
    // resume rather than a fresh run.
    //
    // The resume is attempted whatever the first attempt reported, and including
    // its own `Deadline`: a caller that asked for a budget has already been told
    // the budget is exceeded, and the resume cannot make that answer worse — it
    // can only turn an interrupted run into a finished one.
    let resumed = host.resume(run, &work, 0u32).await;
    into_result(&resumed, &failed)
}

//! Reference solution — `tenant-cache`, FAN API (one-call fan-out).
//!
//! The lightweight end of the facade: no host, one item through the fan-out,
//! with the token checked before anything is read. Isolation is the same
//! property as the `new` arm's — nothing shared between tenants — reached
//! without per-call admission: the fan-out owns the single read the way it
//! would own a thousand.

/// The task's vocabulary, glob-re-exported so the oracle resolves its names.
pub use ai_task_support::tenant_cache::*;
use lgwks_bot::script::FanOut;

pub async fn solve(tenant: &str, resource: &str, token: &str) -> Result<Vec<u8>, CacheError> {
    let admitted: Result<(), CacheError> = if token == format!("token-for-{tenant}") {
        Ok(())
    } else {
        ai_task_support::diagnostic(format_args!("tenant-cache fan arm refused: bad token"));
        Err(CacheError::Refused)
    };
    admitted?;
    let who = tenant.to_owned();
    let what = resource.to_owned();
    let mut values = FanOut::new([(who, what)])
        .at_most(1)
        .run(|(tenant, resource)| async move {
            Ok::<_, CacheError>(format!("value-of-{tenant}-{resource}").into_bytes())
        })
        .await
        .map_err(|error| {
            ai_task_support::diagnostic(format_args!("tenant-cache fan arm: fan-out refused: {error:?}"));
            CacheError::Refused
        })?;
    values.pop().ok_or(CacheError::Refused)
}

//! Reference solution — `aggregate`, FUTURES API (`futures::stream`).
//!
//! The ecosystem-standard answer: `buffer_unordered` bounds the fan-out and
//! `try_fold` stops at the first failure, dropping every fetch still running.
//! `buffer_unordered` rather than `buffered` so a fast failure is observed even
//! while an earlier, slower fetch is still in flight.

use std::time::Duration;

use ai_task_support::Fetcher;
use futures::{StreamExt, TryStreamExt, stream};
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(ids: Vec<u32>, fetch: Fetcher, deadline: Duration) -> Result<u64, SolveError> {
    let work = stream::iter(ids)
        .map(|id| {
            let fetch = fetch.clone();
            async move {
                fetch
                    .fetch(id)
                    .await
                    .map_err(|error| SolveError::Fetch { id: error.id() })
            }
        })
        .buffer_unordered(4)
        .try_fold(0_u64, |sum, value| async move { Ok(sum + value) });
    timeout(deadline, work)
        .await
        .ok()
        .ok_or(SolveError::Deadline)?
}

//! Reference solution — `capture`, FUTURES API (the ecosystem standard).
//!
//! The negative control: a plain blocking `Command::output` retains everything
//! the child writes and waits for every process holding the pipes, so a flood
//! overruns any bound, an orphaned grandchild outlives the call, and a sleep
//! past the deadline cannot be hurried. It must FAIL the oracle's bound,
//! orphan and deadline clauses, which is what makes the oracle's pass on the
//! other arms evidence about the guarantee rather than the task.

use std::time::Duration;

/// The task's vocabulary, glob-re-exported so the oracle resolves its names.
pub use ai_task_support::capture::*;

pub async fn solve(
    argv: Vec<String>,
    head_limit: usize,
    deadline: Duration,
) -> Result<CaptureResult, CaptureError> {
    let mut words = argv;
    let program = if words.is_empty() {
        ai_task_support::diagnostic(format_args!("capture futures arm: empty argv"));
        Err(CaptureError::Spawn("empty argv".to_owned()))
    } else {
        Ok(words.remove(0))
    }?;
    let mut command = std::process::Command::new(program);
    for arg in words {
        command.arg(arg);
    }
    // Blocking, unbounded and unowned: the call returns when the pipes close,
    // with everything retained and nobody reaped.
    let started = std::time::Instant::now();
    let output = command
        .output()
        .map_err(|source| CaptureError::Spawn(source.to_string()))?;
    if started.elapsed() <= deadline {
        let total = u64::try_from(output.stdout.len()).map_err(|error| {
            ai_task_support::diagnostic(format_args!(
                "capture futures arm: output too large to count: {error:?}"
            ));
            CaptureError::Spawn("output too large to count".to_owned())
        })?;
        let kept: Vec<u8> = output.stdout.iter().copied().take(head_limit).collect();
        Ok(CaptureResult::new(kept, total, false))
    } else {
        ai_task_support::diagnostic(format_args!("capture futures arm: the run outlived its deadline"));
        Err(CaptureError::Deadline)
    }
}

//! Reference solution — `durable-retry`, FUTURES API (the ecosystem standard).
//!
//! The negative control: it appends on every call without ever reading the
//! record back, so a restart after a kill applies the effect a second time.
//! It must FAIL the oracle's exactly-once clauses, which is what makes the
//! oracle's pass on the other arms evidence about the idempotency record
//! rather than the task.

use std::path::PathBuf;
use std::time::Duration;

use ai_task_support::durable::{append_application, is_released};

pub use ai_task_support::durable::RecoverError; // futures arm

pub async fn solve(
    effect_dir: PathBuf,
    key: String,
    deadline: Duration,
) -> Result<String, RecoverError> {
    std::fs::create_dir_all(&effect_dir).map_err(|error| {
        ai_task_support::diagnostic(format_args!("durable-retry futures arm: create_dir_all failed: {error:?}"));
        RecoverError::Deadline
    })?;
    // No read-before-apply: every call appends, so a recovery duplicates.
    append_application(&effect_dir, &key).map_err(|error| {
        ai_task_support::diagnostic(format_args!("durable-retry futures arm: append failed: {error:?}"));
        RecoverError::Deadline
    })?;
    let started = std::time::Instant::now();
    loop {
        if is_released(&effect_dir) {
            return Ok(format!("applied:{key}"));
        }
        if started.elapsed() > deadline {
            break;
        }
        lgwks_bot::rt::time::sleep(Duration::from_millis(10)).await;
    }
    ai_task_support::diagnostic(format_args!("durable-retry futures arm: no release arrived before the deadline"));
    Err(RecoverError::Deadline)
}

//! Reference solution — `pipeline`, FUTURES API (`futures::future`).
//!
//! `try_join` runs the two fetches concurrently and drops the survivor on the
//! first failure; the rest is sequential; `timeout` carries the deadline and drops
//! the whole pipeline when it expires.

use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};
use futures::future::try_join;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

async fn run_stage(stage: &Stage, name: StageName) -> Result<Artifact, PipelineError> {
    stage.run(name).await.map_err(|error| match error {
        StageError::Stage { name } => PipelineError::Stage { name },
    })
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let work = async {
        try_join(
            run_stage(&stage, StageName::FetchA),
            run_stage(&stage, StageName::FetchB),
        )
        .await?;
        run_stage(&stage, StageName::Combine).await?;
        run_stage(&stage, StageName::Publish).await.map(Published::from)
    };
    timeout(deadline, work)
        .await
        .ok()
        .ok_or(PipelineError::Deadline)?
}

//! Reference solution — `tenant-cache`, FUTURES API (the ecosystem standard).
//!
//! The negative control: one process-wide map keyed by the resource alone,
//! with the token accepted unread. The first tenant to ask for a resource
//! decides what every later tenant observes, and any token opens any tenant's
//! reads. It must FAIL the oracle's isolation and refusal clauses, which is
//! what makes the oracle's pass on the other arms evidence about the
//! guarantee rather than the task.

use std::collections::HashMap;
use std::sync::{Mutex, OnceLock};

/// The task's fixed refusal.
pub use ai_task_support::tenant_cache::CacheError;

/// The whole cache: resource to bytes, with no tenant anywhere in the key and
/// no authority anywhere in the call.
fn shared() -> &'static Mutex<HashMap<String, Vec<u8>>> {
    static CACHED: OnceLock<Mutex<HashMap<String, Vec<u8>>>> = OnceLock::new();
    CACHED.get_or_init(|| Mutex::new(HashMap::new()))
}

pub async fn solve(tenant: &str, resource: &str, _token: &str) -> Result<Vec<u8>, CacheError> {
    let mut held = match shared().lock() {
        Ok(guard) => guard,
        Err(poisoned) => poisoned.into_inner(),
    };
    if let Some(found) = held.get(resource) {
        return Ok(found.clone());
    }
    let value = format!("value-of-{tenant}-{resource}").into_bytes();
    held.insert(resource.to_owned(), value.clone());
    Ok(value)
}

//! Reference solution — `aggregate`, SCRIPT arm (the `script!` language).
//!
//! The fan-out is a flow: `each` bounded by a named width, with the first
//! failure recorded into a cell the flow takes as an argument. The plain
//! `solve` keeps the deadline, the tenant and the error mapping; the flow
//! keeps the orchestration. A `record_first_failure` helper holds the only
//! lock, so the flow body stays straight-line Rust with no branching past one
//! `if`.

use std::sync::{Arc, Mutex};
use std::time::Duration;

/// The error type this task resolves.
pub use ai_task_support::aggregate::SolveError as SolveError;
use ai_task_support::Fetcher;
use lgwks_bot::script::{FlowError, Scope, Tenant, within};

/// Remember the first id whose fetch failed, ignoring every later one.
///
/// Whole-value assignment under the lock: the cell holds `None` or one id, so
/// a panic elsewhere cannot leave it half-written, and taking the poisoned
/// guard's value keeps the failure the run actually saw first.
fn record_first_failure(failed: &Mutex<Option<u32>>, id: u32) {
    let mut guard = match failed.lock() {
        Ok(guard) => guard,
        Err(poisoned) => poisoned.into_inner(),
    };
    if guard.is_none() {
        *guard = Some(id);
    }
}

lgwks_bot::script! {
    /// Fetch every id, four at a time, and sum the values.
    flow gather(
        ids: Vec<u32>,
        fetch: ai_task_support::Fetcher,
        failed: std::sync::Arc<std::sync::Mutex<Option<u32>>>,
        width: usize,
    ) -> u64:
        let partials = each id in ids, at most (width) at once:
            let outcome = fetch.fetch(id).await
            if outcome.is_err():
                record_first_failure(&failed, id)
                fail with "fetch failed"
            outcome.or_fail()?
        give back partials.into_iter().sum()
}

/// The caller's cancellation, naming the cause on the trace stream.
fn cancelled(cause: impl std::fmt::Debug) -> SolveError {
    ai_task_support::diagnostic(format_args!("aggregate script arm cancelled: {cause:?}"));
    SolveError::Cancelled
}

/// Refuse with `Deadline` as the whole answer, naming the cause on the trace
/// stream. A `return Err(..)` names no cause; returning this names it.
fn err_deadline<T>(cause: impl std::fmt::Debug) -> Result<T, SolveError> {
    ai_task_support::diagnostic(format_args!("aggregate script arm deadline: {cause:?}"));
    Err(SolveError::Deadline)
}

/// Refuse with `Cancelled` as the whole answer, naming the cause on the trace
/// stream. A `return Err(..)` names no cause; returning this names it.
fn err_cancelled<T>(cause: impl std::fmt::Debug) -> Result<T, SolveError> {
    ai_task_support::diagnostic(format_args!("aggregate script arm: already cancelled: {cause:?}"));
    Err(SolveError::Cancelled)
}

pub async fn solve(ids: Vec<u32>, fetch: Fetcher, deadline: Duration) -> Result<u64, SolveError> {
    let tenant = Tenant::new("aggregate").map_err(cancelled)?;
    let outer = Scope::root(tenant);
    let inner = outer.clone();
    let failed: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));
    let failed_for_outcome = Arc::clone(&failed);
    let outcome = within(&outer, "deadline", deadline, async move {
        gather(&inner, ids, fetch, failed, 4).await
    })
    .await;
    if let Err(FlowError::TimedOut { .. }) = outcome {
        return err_deadline("the deadline scope timed out");
    }
    if let Err(FlowError::Cancelled { .. }) = outcome {
        return err_cancelled("the deadline scope was cancelled");
    }
    if outcome.is_ok() {
        return outcome.map_err(cancelled);
    }
    match failed_for_outcome.lock() {
        Ok(guard) => match *guard {
            Some(id) => Err(SolveError::Fetch { id }),
            None => Err(SolveError::Cancelled),
        },
        Err(poisoned) => match *poisoned.into_inner() {
            Some(id) => Err(SolveError::Fetch { id }),
            None => Err(SolveError::Cancelled),
        },
    }
}

//! Reference solution — `capture`, SCRIPT arm (the `script!` language).
//!
//! The flow owns the run the way the `new` reference does, written as a flow:
//! a `step` scope around the supervised run, `fail with` for the two ways a
//! run never settles, and the outcome as data the plain `solve` maps onto the
//! task's errors. The `spawn:` / `cancelled` reason markers are this file's
//! own convention for carrying the run's verdict through `FlowError::Failed`,
//! which is the only error a flow returns.

use std::num::NonZeroUsize;
use std::time::Duration;

/// Re-exported task vocabulary for the oracle.
pub use ai_task_support::capture::CaptureResult;
/// Re-exported task error for the oracle.
pub use ai_task_support::capture::CaptureError;
use lgwks_bot::rt::process::{ProcessRunError, ProcessSpec};
use lgwks_bot::rt::supervise::Supervisor;
use lgwks_bot::script::{FlowError, Scope, Tenant};

/// Refuse a spawn, naming why on the trace stream.
fn spawn(note: &str) -> CaptureError {
    ai_task_support::diagnostic(format_args!("capture script arm: spawn refused: {note}"));
    CaptureError::Spawn(note.to_owned())
}

/// Refuse with `Deadline` as the whole answer, naming the cause on the trace
/// stream. A `return Err(..)` names no cause; returning this names it.
fn err_deadline<T>(cause: impl std::fmt::Debug) -> Result<T, CaptureError> {
    ai_task_support::diagnostic(format_args!("capture script arm deadline: {cause:?}"));
    Err(CaptureError::Deadline)
}

lgwks_bot::script! {
    /// Run one command under supervision and hand back its outcome.
    flow supervised(
        program: String,
        args: Vec<String>,
        head_limit: usize,
        deadline: Duration,
    ) -> (Vec<u8>, u64, bool, bool):
        let limit = NonZeroUsize::new(head_limit).ok_or("zero head_limit").or_fail()?
        let mut detail = ProcessSpec::new(program)
        for arg in args:
            detail.arg(arg)
        detail.capture_stdout(limit)
        detail.capture_stderr(limit)
        detail.deadline(deadline)
        let mut owned = Supervisor::new(1)
        let outcome = owned.run_process(&detail).await
        if matches!(outcome, Err(ProcessRunError::NotStarted { .. })):
            fail with "spawn: the program did not start"
        if outcome.is_err():
            fail with "cancelled: stopped while running"
        let finished = outcome.or_fail()?
        let kept = finished.stdout()
        give back (
            kept.bytes().to_vec(),
            kept.total_bytes(),
            kept.truncated(),
            finished.deadline_fired(),
        )
}

pub async fn solve(
    argv: Vec<String>,
    head_limit: usize,
    deadline: Duration,
) -> Result<CaptureResult, CaptureError> {
    let (program, args) = argv
        .split_first()
        .map(|(first, rest)| (first.clone(), rest.to_vec()))
        .ok_or_else(|| spawn("empty argv"))?;
    let tenant = Tenant::new("capture").map_err(|error| CaptureError::Spawn(error.to_string()))?;
    let scope = Scope::root(tenant);
    match supervised(&scope, program, args, head_limit, deadline).await {
        Ok((head, total, truncated, fired)) => {
            if fired {
                return err_deadline("the run outlived its deadline");
            }
            Ok(CaptureResult::new(head, total, truncated))
        }
        Err(FlowError::Failed { reason, .. }) if reason.starts_with("spawn:") => {
            Err(CaptureError::Spawn(reason))
        }
        Err(FlowError::Failed { .. }) => Err(CaptureError::Cancelled),
        Err(FlowError::TimedOut { .. }) => Err(CaptureError::Deadline),
        Err(other) => Err(CaptureError::Spawn(other.to_string())),
    }
}

//! Reference solution — `durable-retry`, SCRIPT arm (the `script!` language).
//!
//! The record discipline is plain Rust — read before appending, exactly one
//! line per key — and the wait is a flow: a `retry` block that returns the
//! status the moment the release file exists, fails the deadline the moment
//! it passes, and otherwise waits transiently. The flow never returns
//! `Unknown`: a missing release is a wait, never a verdict.

use std::path::PathBuf;
use std::time::Duration;

use lgwks_bot::script::{FlowError, Scope, Tenant};

pub use ai_task_support::durable::RecoverError; // script arm

/// Refuse with `Deadline`, naming the cause on the trace stream.
fn deadline(cause: impl std::fmt::Debug) -> RecoverError {
    ai_task_support::diagnostic(format_args!("durable-retry script arm refused: {cause:?}"));
    RecoverError::Deadline
}

lgwks_bot::script! {
    /// Wait for the release file, then hand back the settled status.
    flow await_release(dir: PathBuf, status: String, deadline: Duration) -> String:
        let started = std::time::Instant::now()
        for _attempt in 0..1000u32:
            if started.elapsed() > deadline:
                fail with "deadline"
            if std::path::Path::new(&dir.join("release")).exists():
                give back status
            lgwks_bot::rt::time::sleep(std::time::Duration::from_millis(100)).await
        fail with "release never appeared"
}

pub async fn solve(
    home: PathBuf,
    job: String,
    span: Duration,
) -> Result<String, RecoverError> {
    use ai_task_support::durable::{append_application, has_application};
    std::fs::create_dir_all(&home).map_err(deadline)?;
    let settled_before = has_application(&home, &job).map_err(deadline)?;
    if !settled_before {
        append_application(&home, &job).map_err(deadline)?;
    }
    let status = if settled_before {
        format!("recovered:{job}")
    } else {
        format!("applied:{job}")
    };
    let scope = Scope::root(Tenant::new("durable").map_err(deadline)?);
    match await_release(&scope, home, status, span).await {
        Ok(done) => Ok(done),
        Err(FlowError::Failed { reason, .. }) if reason == "deadline" => {
            Err(RecoverError::Deadline)
        }
        Err(FlowError::Exhausted { .. }) | Err(FlowError::TimedOut { .. }) => {
            Err(RecoverError::Deadline)
        }
        Err(_) => Err(RecoverError::Unknown),
    }
}

//! Reference solution — `pipeline`, SCRIPT arm (the `script!` language).
//!
//! The fetch pair is a flow: `together` runs both fetches concurrently and the
//! first failure stops the sibling, then `combine` and `publish` run in turn.
//! A shared cell records which stage failed first; the plain `solve` keeps the
//! tenant, the deadline and the error mapping, reading the cell only when the
//! flow itself cannot name the failure.

use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::{Published, Stage, StageName};
use lgwks_bot::script::{FlowError, Scope, Tenant, within};

/// The task's fixed stage error.
pub use ai_task_support::pipeline::PipelineError;

/// Remember the stage that failed first, leaving a recorded stage alone.
///
/// Whole-value assignment under the lock: the cell holds `None` or one name,
/// so a panic elsewhere cannot leave it half-written.
fn record_stage(failed: &Mutex<Option<StageName>>, name: StageName) {
    let mut guard = match failed.lock() {
        Ok(guard) => guard,
        Err(poisoned) => poisoned.into_inner(),
    };
    if guard.is_none() {
        *guard = Some(name);
    }
}

/// Read the recorded stage, defaulting to cancellation when none failed.
///
/// A separate function rather than an inline match: the flow cannot name a
/// failure that never reached a stage, and blaming `FetchA` for the flow's
/// own error would indict a stage that ran and succeeded.
fn recorded_or_cancelled(failed: &Mutex<Option<StageName>>) -> PipelineError {
    match failed.lock() {
        Ok(guard) => match *guard {
            Some(name) => PipelineError::Stage { name },
            None => PipelineError::Cancelled,
        },
        Err(poisoned) => match *poisoned.into_inner() {
            Some(name) => PipelineError::Stage { name },
            None => PipelineError::Cancelled,
        },
    }
}

lgwks_bot::script! {
    /// Run one stage, recording its name when it fails.
    flow fetch_single(
        stage: ai_task_support::Stage,
        name: ai_task_support::StageName,
        failed: std::sync::Arc<std::sync::Mutex<Option<ai_task_support::StageName>>>,
    ) -> u64:
        let outcome = stage.run(name).await
        if outcome.is_err():
            record_stage(&failed, name)
            fail with "stage failed"
        give back outcome.or_fail()?.value()

    /// Run both fetches concurrently; the first failure stops the sibling.
    flow fetch_both(
        stage: ai_task_support::Stage,
        failed: std::sync::Arc<std::sync::Mutex<Option<ai_task_support::StageName>>>,
    ) -> (u64, u64):
        let other = stage.clone()
        let failed_a = failed.clone()
        together:
            let a = run fetch_single(stage, ai_task_support::StageName::FetchA, failed_a)
            let b = run fetch_single(other, ai_task_support::StageName::FetchB, failed)
        give back (a, b)

    /// Fetch, combine and publish in order.
    flow run_pipeline(
        stage: ai_task_support::Stage,
        failed: std::sync::Arc<std::sync::Mutex<Option<ai_task_support::StageName>>>,
    ) -> ai_task_support::Published:
        let worker = stage.clone()
        let failed_later = failed.clone()
        let _fetched = run fetch_both(worker, failed)
        let combined_outcome = stage.run(ai_task_support::StageName::Combine).await
        if combined_outcome.is_err():
            record_stage(&failed_later, ai_task_support::StageName::Combine)
            fail with "combine failed"
        let combined = combined_outcome.or_fail()?
        let published_outcome = stage.run(ai_task_support::StageName::Publish).await
        if published_outcome.is_err():
            record_stage(&failed_later, ai_task_support::StageName::Publish)
            fail with "publish failed"
        give back ai_task_support::Published::from(published_outcome.or_fail()?)
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let tenant = Tenant::new("pipeline").map_err(|error| {
        ai_task_support::diagnostic(format_args!("pipeline script arm: tenant refused: {error:?}"));
        PipelineError::Cancelled
    })?;
    let outer = Scope::root(tenant);
    let failed: Arc<Mutex<Option<StageName>>> = Arc::new(Mutex::new(None));
    let failed_for_outcome = Arc::clone(&failed);
    let inner = outer.clone();
    let outcome = within(&outer, "deadline", deadline, async move {
        run_pipeline(&inner, stage, failed).await
    })
    .await;
    match outcome {
        Ok(published) => Ok(published),
        Err(FlowError::TimedOut { .. }) => Err(PipelineError::Deadline),
        Err(FlowError::Cancelled { .. }) => Err(PipelineError::Cancelled),
        Err(_) => Err(recorded_or_cancelled(&failed_for_outcome)),
    }
}

//! Reference solution — `recovery`, SCRIPT arm (the `script!` language).
//!
//! The units loop is a flow: `for` over the world's width, each unit awaited
//! in turn, the first failure returning early with its index. The effect
//! applies once by reading the ledger before applying, in plain Rust beside
//! the flow. The plain `recover` keeps the derived run identity, the host and
//! the run-then-resume orchestration; the flow keeps the per-unit work.
//!
//! Two deliberate differences from the `new` arm, both load-bearing. The
//! failure index travels in the flow's own outcome enum rather than a shared
//! `Option` cell, and the "no failure recorded" sentinel is `u32::MAX`
//! rather than `None`: a second spelling of the same contract, so a defect in
//! one spelling shows up as a divergence rather than a shared blind spot.

use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::recovery::{Ledger, World};
use lgwks_bot::effect::RunId;
use lgwks_bot::script::Scope;
use lgwks_bot::task::{Disposition, Host, task};

/// The task's fixed recovery error.
pub use ai_task_support::recovery::RecoveryError;

/// The tenant every recovered run is booked under.
const TENANT: &str = "recovery";

/// The effect name the ledger is asked to apply exactly once.
const EFFECT: &str = "recover";

/// The run identity, derived rather than minted.
///
/// Any stable non-zero 32-hex value works: both attempts derive the same run
/// so the second finds the first attempt's records. A freshly minted identity
/// per call would derive a different run every time and the resume would find
/// nothing.
const RUN: &str = "7e4b1c90d2f848632a7e5b4c9d1f3a01";

/// Which unit failed, or that none has: `u32::MAX` means no failure recorded.
type FailedUnit = Arc<Mutex<u32>>;

/// Note the first unit that failed, leaving a recorded failure alone.
fn note_failure(failed: &Mutex<u32>, index: u32) {
    let mut guard = match failed.lock() {
        Ok(guard) => guard,
        Err(poisoned) => poisoned.into_inner(),
    };
    if *guard == u32::MAX {
        *guard = index;
    }
}

/// Refuse with `NoStore` as the whole answer, naming the cause on the trace
/// stream. A `return Err(..)` names no cause; returning this names it.
fn err_no_store<T>(cause: impl std::fmt::Debug) -> Result<T, RecoveryError> {
    ai_task_support::diagnostic(format_args!("recovery script arm: no store: {cause:?}"));
    Err(RecoveryError::NoStore)
}

/// Refuse with `Deadline` as the whole answer, naming the cause on the trace
/// stream. A `return Err(..)` names no cause; returning this names it.
fn err_deadline<T>(cause: impl std::fmt::Debug) -> Result<T, RecoveryError> {
    ai_task_support::diagnostic(format_args!("recovery script arm deadline: {cause:?}"));
    Err(RecoveryError::Deadline)
}

lgwks_bot::script! {
    /// Run every unit in turn, stopping at the first failure.
    flow work_units(world: ai_task_support::recovery::World, failed: std::sync::Arc<std::sync::Mutex<u32>>) -> u64:
        let mut total = 0u64
        for index in 0..world.width():
            let outcome = world.unit(&scope, index).await
            if outcome.is_err():
                note_failure(&failed, index)
                fail with "unit failed"
            total = total.saturating_add(outcome.or_fail()?)
        let ledger = world.ledger().clone()
        if !ledger.applied("recover"):
            ledger.apply("recover")
        give back total
}

/// Read one attempt's outcome into the caller's error type.
fn settled(report: &lgwks_bot::task::Report<u64>, failed: &FailedUnit) -> Result<u64, RecoveryError> {
    if report.disposition().is_success() {
        return report.output().copied().ok_or(RecoveryError::NoLedger);
    }
    if report.disposition() == Disposition::DeadlineExceeded {
        return err_deadline("deadline exceeded");
    }
    let recorded = match failed.lock() {
        Ok(guard) => *guard,
        Err(poisoned) => *poisoned.into_inner(),
    };
    if recorded == u32::MAX {
        return err_no_store("no failure recorded");
    }
    Err(RecoveryError::Unit { index: recorded })
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let run = RunId::from_hex(RUN).map_err(|error| {
        ai_task_support::diagnostic(format_args!("recovery script arm: run identity refused: {error:?}"));
        RecoveryError::NoStore
    })?;
    let host = Host::builder(TENANT)
        .map_err(|error| {
            ai_task_support::diagnostic(format_args!("recovery script arm: tenant refused: {error:?}"));
            RecoveryError::NoStore
        })?
        .default_deadline(deadline)
        .run_store(&store_dir)
        .map_err(|error| {
            ai_task_support::diagnostic(format_args!("recovery script arm: run store refused: {error:?}"));
            RecoveryError::NoStore
        })?
        .build()
        .map_err(|error| {
            ai_task_support::diagnostic(format_args!("recovery script arm: host build refused: {error:?}"));
            RecoveryError::NoStore
        })?;
    let failed: FailedUnit = Arc::new(Mutex::new(u32::MAX));
    let failed_for_settled = Arc::clone(&failed);
    let work = task("flow-units", move |scope: Scope, _attempt: u32| {
        let world = world.clone();
        let failed = Arc::clone(&failed);
        async move { work_units(&scope, world, failed).await }
    })
    .map_err(|error| {
        ai_task_support::diagnostic(format_args!("recovery script arm: task refused: {error:?}"));
        RecoveryError::NoStore
    })?;

    // The first attempt. Whatever it reaches, its records are already on the
    // disk, so the resume below can find them.
    let first = host.run(&work, 0u32).await;
    let done = settled(&first, &failed_for_settled);
    if done.is_ok() {
        return done;
    }

    // The second attempt, under the same derived run: recorded units replay
    // without their bodies running again, and the units the first attempt did
    // not reach run now.
    let resumed = host.resume(run, &work, 0u32).await;
    settled(&resumed, &failed_for_settled)
}

//! Reference solution — `tenant-cache`, SCRIPT arm (the `script!` language).
//!
//! Authority still lives in the host's grants, but the read itself is a flow:
//! a `step` scope around the require and the value, called from a thin task
//! body. The flow is where an author would hang more steps — audit, fallback,
//! fan-out — without touching the admission boundary around it.

/// The task's refusal, aliased so the oracle resolves it.
pub use ai_task_support::tenant_cache::CacheError as CacheError;
use lgwks_bot::gate::GrantSet;
use lgwks_bot::script::Scope;
use lgwks_bot::task::{Host, task};

lgwks_bot::script! {
    /// Read one tenant's value under the run's authority.
    flow serve_value(tenant: String, resource: String) -> Vec<u8>:
        step authorised:
            scope.require(&[lgwks_bot::cap::Cap::new("cache.read")])?
            format!("value-of-{tenant}-{resource}").into_bytes()
}

/// Refuse the read, naming the failed step on the trace stream.
fn refused(cause: impl std::fmt::Debug) -> CacheError {
    ai_task_support::diagnostic(format_args!("tenant-cache script arm refused: {cause:?}"));
    CacheError::Refused
}

pub async fn solve(tenant: &str, resource: &str, token: &str) -> Result<Vec<u8>, CacheError> {
    // The token buys the cache capability for the tenant's own token and
    // nothing otherwise; the decision is inline because this arm keeps the
    // whole admission where the host is built.
    let admitted = if token == format!("token-for-{tenant}") {
        GrantSet::empty().grant(lgwks_bot::cap::Cap::new("cache.read"))
    } else {
        GrantSet::empty()
    };
    let host = Host::builder(tenant)
        .map_err(refused)?
        .grants(admitted)
        .build()
        .map_err(refused)?;
    let owned_tenant = tenant.to_owned();
    let owned_resource = resource.to_owned();
    let work = task("serve", move |scope: Scope, _: ()| {
        let owned_tenant = owned_tenant.clone();
        let owned_resource = owned_resource.clone();
        async move { serve_value(&scope, owned_tenant, owned_resource).await }
    })
    .map_err(refused)?;
    // Any non-success — Blocked, Failed, Cancelled — is a refusal: the value
    // is only readable under the run's authority.
    host.run(&work, ()).await.into_result().map_err(refused)
}

//! Reference solution — `aggregate`, NEW API (`lgwks_bot::script`).
//!
//! This is the hand-written proof that the task is solvable on the task/script
//! facade, and the dry-run's canned solution. It is intentionally short: the
//! point of the measurement is how much orchestration the author must write.

use std::num::NonZeroUsize;
use std::sync::{Arc, Mutex, MutexGuard};
use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::script::{FlowError, Scope, Tenant, each, within};

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

/// The caller's cancellation, naming why the tenant could not be opened.
fn cancelled(cause: impl std::fmt::Debug) -> SolveError {
    ai_task_support::diagnostic(format_args!("the aggregate tenant was refused: {cause:?}"));
    SolveError::Cancelled
}

/// Locks `mutex`, recovering from poisoning.
///
/// The guarded value is an `Option<u32>` that is only ever written as a whole
/// `Some(id)` or left alone, so a panic elsewhere cannot leave it half-written:
/// poisoning records that some thread unwound while holding the guard, not that
/// the recorded id is unreadable. Taking the poisoned guard's value keeps the
/// first failure the run actually saw, which is the id the caller is told.
fn lock<T>(mutex: &Mutex<T>) -> MutexGuard<'_, T> {
    match mutex.lock() {
        Ok(guard) => guard,
        Err(poisoned) => poisoned.into_inner(),
    }
}

pub async fn solve(ids: Vec<u32>, fetch: Fetcher, deadline: Duration) -> Result<u64, SolveError> {
    let tenant = Tenant::new("aggregate").map_err(cancelled)?;
    let outer_scope = Scope::root(tenant);
    let bound = NonZeroUsize::new(4).ok_or(SolveError::Cancelled)?;
    // `None` means no fetch has failed. A plain `0` would say fetch id 0 had
    // failed whether or not any fetch had, and a failure of the tenant itself
    // would be reported as a fetch error against an id nobody asked for.
    let failed: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));

    let scope_for_await = outer_scope.clone();
    let fetch_for_await = fetch;
    let failed_for_await = Arc::clone(&failed);
    let outcome = within(&outer_scope, "deadline", deadline, async move {
        let worker = {
            let fetch = fetch_for_await.clone();
            let failed = Arc::clone(&failed_for_await);
            move |_step: Scope, id: u32| {
                let fetch = fetch.clone();
                let failed = Arc::clone(&failed);
                async move {
                    match fetch.fetch(id).await {
                        Ok(value) => Ok(value),
                        Err(_) => {
                            let mut recorded = lock(&failed);
                            // The *first* failure names the run, so a later
                            // failure cannot overwrite the id the caller hears.
                            if recorded.is_none() {
                                *recorded = Some(id);
                            }
                            Err(FlowError::failed("fetch failed"))
                        }
                    }
                }
            }
        };
        let values = each(&scope_for_await, "fetch", Some(bound), ids, worker).await?;
        Ok(values.into_iter().sum())
    })
    .await;

    match outcome {
        Ok(sum) => Ok(sum),
        Err(FlowError::TimedOut { .. }) => Err(SolveError::Deadline),
        Err(FlowError::Cancelled { .. }) => Err(SolveError::Cancelled),
        Err(cause) => match *lock(&failed) {
            Some(id) => Err(SolveError::Fetch { id }),
            None => {
                // No fetch failed, so the error came from the fan-out itself and
                // naming a fetch id would blame a fetch that succeeded.
                ai_task_support::diagnostic(format_args!(
                    "the aggregate fan-out failed with no fetch having failed: {cause}"
                ));
                Err(SolveError::Cancelled)
            }
        },
    }
}

//! Reference solution — `capture`, NEW API (task facade + supervised run).
//!
//! The sanctioned runner does the owning: `run_process` captures at most the
//! declared head bytes however much the child writes, stops the whole process
//! group past the deadline, and dropping the future stops the tree it named.
//! The solution maps that report onto the task's error vocabulary and adds
//! nothing of its own.

use std::num::NonZeroUsize;
use std::time::Duration;

/// The task's fixed vocabulary, re-exported: the oracle names these items,
/// and one definition serves every arm.
pub use ai_task_support::capture::{CaptureError, CaptureResult};
use lgwks_bot::rt::process::{ProcessRunError, ProcessSpec};
use lgwks_bot::rt::supervise::Supervisor;

/// Refuse with `Deadline` as the whole answer, naming the cause on the trace
/// stream. A `return Err(..)` names no cause; returning this names it.
fn err_deadline<T>(cause: impl std::fmt::Debug) -> Result<T, CaptureError> {
    ai_task_support::diagnostic(format_args!("capture new arm deadline: {cause:?}"));
    Err(CaptureError::Deadline)
}

pub async fn solve(
    argv: Vec<String>,
    head_limit: usize,
    deadline: Duration,
) -> Result<CaptureResult, CaptureError> {
    let mut parts = argv.into_iter();
    let program = parts.next().ok_or_else(|| CaptureError::Spawn("empty argv".to_owned()))?;
    let limit = NonZeroUsize::new(head_limit)
        .ok_or_else(|| CaptureError::Spawn("head_limit is zero".to_owned()))?;
    let mut spec = ProcessSpec::new(program);
    for arg in parts {
        spec.arg(arg);
    }
    // Both streams are captured so a chatty stderr cannot wedge the child on a
    // full pipe while nobody reads it.
    spec.capture_stdout(limit);
    spec.capture_stderr(limit);
    spec.deadline(deadline);
    let mut supervisor = Supervisor::new(4);
    match supervisor.run_process(&spec).await {
        Ok(run) => {
            if run.deadline_fired() {
                return err_deadline("the run outlived its deadline");
            }
            let captured = run.stdout();
            Ok(CaptureResult::new(
                captured.bytes().to_vec(),
                captured.total_bytes(),
                captured.truncated(),
            ))
        }
        Err(ProcessRunError::NotStarted { source }) => {
            Err(CaptureError::Spawn(source.to_string()))
        }
        Err(_) => Err(CaptureError::Cancelled),
    }
}

//! Reference solution — `durable-retry`, NEW API (record + `retry` wait).
//!
//! The record discipline is the same file the `old` arm keeps: read before
//! appending, exactly one line per key. What the facade adds here is the wait:
//! `retry` polls the release file with a bounded backoff instead of a
//! hand-rolled sleep loop, and a missed deadline is a typed `Failed` rather
//! than a branch the author remembers to write.

use std::path::PathBuf;
use std::time::Duration;

use ai_task_support::durable::{append_application, has_application};
use lgwks_bot::script::{FlowError, Scope, Tenant, attempts, retry};

pub use ai_task_support::durable::RecoverError; // new arm

/// Refuse with `Deadline`, naming the cause on the trace stream.
fn deadline(cause: impl std::fmt::Debug) -> RecoverError {
    ai_task_support::diagnostic(format_args!("durable-retry new arm refused: {cause:?}"));
    RecoverError::Deadline
}

pub async fn solve(
    root: PathBuf,
    tag: String,
    wait: Duration,
) -> Result<String, RecoverError> {
    std::fs::create_dir_all(&root).map_err(deadline)?;
    let fresh = !has_application(&root, &tag).map_err(deadline)?;
    if fresh {
        append_application(&root, &tag).map_err(deadline)?;
    }
    let status = if fresh {
        format!("applied:{tag}")
    } else {
        format!("recovered:{tag}")
    };
    let scope = Scope::root(Tenant::new("durable").map_err(deadline)?);
    let started = std::time::Instant::now();
    let release = root.join("release");
    // A thousand polls a hundred milliseconds apart: a hundred seconds of
    // waiting, so the attempt bound never decides a run the deadline still
    // owns. The elapsed check below is what enforces the task's deadline.
    retry(
        &scope,
        "wait-release",
        attempts(1000).map_err(deadline)?,
        Duration::from_millis(100),
        |_, _| {
            let release = release.clone();
            async move {
                if release.exists() {
                    Ok(())
                } else if started.elapsed() > wait {
                    Err(FlowError::failed("deadline"))
                } else {
                    Err(FlowError::transient("waiting for release"))
                }
            }
        },
    )
    .await
    .map_err(deadline)?;
    Ok(status)
}

//! Reference solution — `pipeline`, NEW API (`lgwks_bot::script`).
//!
//! `each` runs `fetch_a` and `fetch_b` concurrently, fails fast and drops the
//! sibling when one fails; `within` carries the deadline and drops the running
//! body when it expires.

use std::num::NonZeroUsize;
use std::sync::{Arc, Mutex, MutexGuard};
use std::time::Duration;

use ai_task_support::{Published, Stage, StageName};
use lgwks_bot::script::{FlowError, Scope, Tenant, each, within};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

/// The caller's cancellation, naming why the tenant could not be opened.
fn cancelled(cause: impl std::fmt::Debug) -> PipelineError {
    ai_task_support::diagnostic(format_args!("the pipeline tenant was refused: {cause:?}"));
    PipelineError::Cancelled
}

/// Locks `mutex`, recovering from poisoning.
///
/// The guarded value is an `Option<StageName>` that is only ever written as a
/// whole `Some(name)` or left alone, so a panic elsewhere cannot leave it
/// half-written: poisoning records that some thread unwound while holding the
/// guard, not that the recorded stage is unreadable. Taking the poisoned guard's
/// value keeps the first stage the run actually failed at, which is the name the
/// caller is told.
fn lock<T>(mutex: &Mutex<T>) -> MutexGuard<'_, T> {
    match mutex.lock() {
        Ok(guard) => guard,
        Err(poisoned) => poisoned.into_inner(),
    }
}

/// Records `name` as the stage this run failed at, if none has been yet.
fn record(failed: &Mutex<Option<StageName>>, name: StageName) {
    let mut recorded = lock(failed);
    // The *first* failure names the run, so a later failure cannot overwrite the
    // stage the caller hears about.
    if recorded.is_none() {
        *recorded = Some(name);
    }
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let tenant = Tenant::new("pipeline").map_err(cancelled)?;
    let outer_scope = Scope::root(tenant);
    let bound = NonZeroUsize::new(2).ok_or(PipelineError::Cancelled)?;
    let failed: Arc<Mutex<Option<StageName>>> = Arc::new(Mutex::new(None));

    let scope_for_await = outer_scope.clone();
    let stage_for_await = stage;
    let failed_for_await = Arc::clone(&failed);
    let outcome = within(&outer_scope, "deadline", deadline, async move {
        // Two handles to one cell: the fan-out's worker moves its own into every
        // concurrent fetch, and the serial stages below record through this one.
        // Both name the same run, so whichever fails first is the one recorded.
        let failed_for_stages = Arc::clone(&failed_for_await);
        let worker = {
            let stage = stage_for_await.clone();
            let failed = Arc::clone(&failed_for_await);
            move |_step: Scope, name: StageName| {
                let stage = stage.clone();
                let failed = Arc::clone(&failed);
                async move {
                    match stage.run(name).await {
                        Ok(artifact) => Ok(artifact.value()),
                        Err(_) => {
                            record(&failed, name);
                            Err(FlowError::failed("stage failed"))
                        }
                    }
                }
            }
        };
        each(
            &scope_for_await,
            "fetch",
            Some(bound),
            [StageName::FetchA, StageName::FetchB],
            worker,
        )
        .await?;
        // `combine` and `publish` can fail for their own sake — an input no
        // earlier stage produced — so their failures are recorded under their
        // own names rather than left unnamed for the caller to default.
        stage_for_await
            .run(StageName::Combine)
            .await
            .map_err(|error| {
                record(&failed_for_stages, StageName::Combine);
                FlowError::failed(format!("combine: {error}"))
            })?;
        let published = stage_for_await
            .run(StageName::Publish)
            .await
            .map_err(|error| {
                record(&failed_for_stages, StageName::Publish);
                FlowError::failed(format!("publish: {error}"))
            })?;
        Ok(Published::from(published))
    })
    .await;

    match outcome {
        Ok(published) => Ok(published),
        Err(FlowError::TimedOut { .. }) => Err(PipelineError::Deadline),
        Err(FlowError::Cancelled { .. }) => Err(PipelineError::Cancelled),
        Err(cause) => match *lock(&failed) {
            Some(name) => Err(PipelineError::Stage { name }),
            None => {
                // No stage failed, so the error came from the flow itself. A
                // default of `FetchA` here would blame a stage that ran and
                // succeeded.
                ai_task_support::diagnostic(format_args!(
                    "the pipeline flow failed with no stage having failed: {cause}"
                ));
                Err(PipelineError::Cancelled)
            }
        },
    }
}

//! Reference solution — `recovery` (NEW API: `lgwks_bot::task` + `script`).
//!
//! There is no OLD-API arm for this task, and the reason is architectural
//! rather than a gap in the harness: the old `lgwks_bot::rt` surface has no
//! durable run store, no `remember`, no run identity and no resume. Nothing in
//! it can express "finish the work without redoing a completed unit", because
//! it keeps no record of a completed unit to consult. A hand-rolled file
//! standing in for that store would measure the fixture the model wrote rather
//! than the crate.
//!
//! Four things have to be right, and this file shows each:
//!
//! 1. **A run identity that is stable across attempts.** [`RunId::from_hex`] over
//!    a digest of the tenant, so every attempt derives the same run and a second
//!    call finds the first call's records. A freshly minted identity per call
//!    would derive a *different* run every time and the resume would find
//!    nothing — the plausible first mistake this task exists to catch.
//! 2. **A durable store installed on the host**, so `remember` has somewhere to
//!    land and `Host::resume` has records to replay.
//! 3. **A helper that builds the task body once**, reused by both attempts. The
//!    step key is derived from the step *path*, so two attempts that spelled the
//!    step differently would record under different keys and never replay.
//! 4. **The effect applied once**, by reading [`Ledger::applied`] before applying.
//!
//! The interruption itself is the harness's business. This code never learns that
//! a first attempt was killed — it is simply correct when `recover` is called
//! again.

use std::path::PathBuf;
use std::sync::{Arc, Mutex, MutexGuard};
use std::time::Duration;

use ai_task_support::recovery::{Ledger, UnitError, World};
use lgwks_bot::effect::RunId;
use lgwks_bot::script::{FlowError, Scope};
use lgwks_bot::task::{Disposition, Host, task};

#[derive(Debug)]
pub enum RecoveryError {
    Unit { index: u32 },
    Deadline,
    NoStore,
    NoLedger,
}

/// The caller's refusal when the store cannot be had, naming why on stderr.
fn no_store(cause: impl std::fmt::Debug) -> RecoveryError {
    ai_task_support::diagnostic(format_args!("the recovery store was refused: {cause:?}"));
    RecoveryError::NoStore
}

/// Locks `mutex`, recovering from poisoning.
///
/// The guarded value is an `Option<u32>` that is only ever written as a whole
/// `Some(index)` or left alone, so a panic elsewhere cannot leave it
/// half-written: poisoning records that some thread unwound while holding the
/// guard, not that the recorded unit is unreadable. Taking the poisoned guard's
/// value keeps the unit the run actually failed at, which is the index the
/// caller is told.
fn lock<T>(mutex: &Mutex<T>) -> MutexGuard<'_, T> {
    match mutex.lock() {
        Ok(guard) => guard,
        Err(poisoned) => poisoned.into_inner(),
    }
}

/// The tenant every recovered run is booked under.
const TENANT: &str = "recovery";

/// The effect name the ledger is asked to apply exactly once.
const EFFECT: &str = "recover";

/// The run identity, derived rather than minted.
///
/// `RunId::mint` needs the estate's entropy source, and a fresh value would be
/// exactly wrong here: a second attempt has to derive the *same* run to find the
/// first attempt's records. So the identity is a digest of the tenant alone,
/// spelled out as a constant rather than recomputed at each call — which also
/// means this file carries no hashing for a solution to get subtly wrong.
const RUN: &str = "0f9d3a17c25b4e806b1de4372f5a9c60";

/// The body every unit runs under.
///
/// `World::unit` enters its own child scope per index, and a scope's key is its
/// *path*, so each unit is already independently keyed. This name is the parent
/// both attempts share, which is what makes the replay find what the first
/// attempt wrote.
const STEP: &str = "units";

/// Which unit failed, read back out of the body's own record.
///
/// Kept beside the failure rather than inside the error type: a task body returns
/// `FlowError`, so the unit index has to travel out-of-band for `recover` to name
/// it in `RecoveryError::Unit { index }`.
type Failed = Arc<Mutex<Option<u32>>>;

/// The future a task body returns, named once so both the task's type parameter
/// and the body that builds it are spelled against the same type.
type Body = std::pin::Pin<Box<dyn std::future::Future<Output = Result<u64, FlowError>>>>;

/// The helper: the one task body both attempts run.
///
/// Built by a function rather than written twice, because "the same task on both
/// attempts" is a property of this function returning the same task. Two
/// hand-written bodies that happen to agree today are two bodies that can drift
/// tomorrow, and that drift would show up as a solution that mysteriously fails
/// to replay rather than as a compile error.
fn recovery_task(
    world: World,
    failed: Failed,
) -> Result<lgwks_bot::task::Task<impl Fn(Scope, u32) -> Body>, RecoveryError> {
    let width = world.width();
    task(STEP, move |scope: Scope, _attempt: u32| -> Body {
        let world = world.clone();
        let failed = Arc::clone(&failed);
        Box::pin(async move {
            let mut total: u64 = 0;
            for index in 0..width {
                let value = world
                    .unit(&scope, index)
                    .await
                    .map_err(|UnitError::Unit { index }| {
                        *lock(&failed) = Some(index);
                        FlowError::failed(format!("unit {index} failed"))
                    })?;
                total = total.saturating_add(value);
            }
            // The exactly-once half. Read the ledger before applying: a replayed
            // run finds the effect already applied and skips it, so the count
            // stays at one across any number of attempts.
            let ledger: Ledger = world.ledger().clone();
            if !ledger.applied(EFFECT) {
                ledger.apply(EFFECT);
            }
            Ok(total)
        })
    })
    .map_err(no_store)
}

/// A host over `store_dir` for `TENANT`, carrying `deadline`.
///
/// One function so both attempts build the same host over the same directory:
/// the store is opened — and its existing records replayed — at
/// [`HostBuilder::run_store`](lgwks_bot::task::HostBuilder::run_store), so the
/// second attempt is the one that finds the first attempt's records.
fn recovery_host(store_dir: &std::path::Path, deadline: Duration) -> Result<Host, RecoveryError> {
    Host::builder(TENANT)
        .map_err(no_store)?
        .default_deadline(deadline)
        .run_store(store_dir)
        .map_err(no_store)?
        .build()
        .map_err(no_store)
}

/// Read the outcome of one attempt into the caller's own error type.
fn into_result(report: &lgwks_bot::task::Report<u64>, failed: &Failed) -> Result<u64, RecoveryError> {
    match report.disposition() {
        Disposition::Succeeded => report
            .output()
            .copied()
            .ok_or(RecoveryError::NoLedger),
        Disposition::DeadlineExceeded => Err(RecoveryError::Deadline),
        _ => {
            let index = lock(&failed);
            Err(match *index {
                Some(index) => RecoveryError::Unit { index },
                None => RecoveryError::NoStore,
            })
        }
    }
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let run = RunId::from_hex(RUN).map_err(no_store)?;
    let host = recovery_host(&store_dir, deadline)?;
    let failed: Failed = Arc::new(Mutex::new(None));
    // The world moves into the task: the caller reads the ledger from the world
    // it already holds, so this frame keeps no clone of its own.
    let work = recovery_task(world, Arc::clone(&failed))?;

    // The first attempt. Whatever it reaches, its records are already on the disk
    // by the time `remember` returned, so the resume below can find them.
    let first = host.run(&work, 0u32).await;
    let settled = into_result(&first, &failed);
    if settled.is_ok() {
        return settled;
    }

    // The second attempt, under the same derived run: every unit the first
    // attempt recorded replays without its body running again, and the units it
    // did not reach run now. The task, the scope and the run identity are the
    // same on both attempts, which is the whole reason this compiles into a
    // resume rather than a fresh run.
    //
    // The resume is attempted whatever the first attempt reported, and including
    // its own `Deadline`: a caller that asked for a budget has already been told
    // the budget is exceeded, and the resume cannot make that answer worse — it
    // can only turn an interrupted run into a finished one.
    let resumed = host.resume(run, &work, 0u32).await;
    into_result(&resumed, &failed)
}

//! Reference solution — `tenant-cache`, NEW API (per-tenant Host authority).
//!
//! Authority lives in the host's grants, not in an `if` the author remembers:
//! a valid token mints a grant for the cache capability and anything else
//! mints nothing, so the body's `require` is where an unauthorised call stops.
//! Isolation needs no map at all — each tenant's host scopes its own run, and
//! the value is derived from the tenant and resource the run was admitted for.

/// The task's fixed refusal.
pub use ai_task_support::tenant_cache::CacheError;
use lgwks_bot::cap::Cap;
use lgwks_bot::gate::GrantSet;
use lgwks_bot::script::{FlowError, Scope};
use lgwks_bot::task::{Host, task};

/// The capability a cache read reaches for.
const READ: &str = "cache.read";

/// The grants a token buys: the cache capability for the tenant's own token,
/// nothing for anything else.
fn grants_for(tenant: &str, token: &str) -> GrantSet {
    if token == format!("token-for-{tenant}") {
        GrantSet::empty().grant(Cap::new(READ))
    } else {
        GrantSet::empty()
    }
}

/// Refuse the read, naming the failed step on the trace stream.
fn refused(cause: impl std::fmt::Debug) -> CacheError {
    ai_task_support::diagnostic(format_args!("tenant-cache new arm refused: {cause:?}"));
    CacheError::Refused
}

pub async fn solve(tenant: &str, resource: &str, token: &str) -> Result<Vec<u8>, CacheError> {
    let host = Host::builder(tenant)
        .map_err(refused)?
        .grants(grants_for(tenant, token))
        .build()
        .map_err(refused)?;
    let owned_tenant = tenant.to_owned();
    let owned_resource = resource.to_owned();
    let work = task("serve", move |scope: Scope, _: ()| {
        let tenant = owned_tenant.clone();
        let resource = owned_resource.clone();
        async move {
            scope.require(&[Cap::new(READ)])?;
            Ok::<_, FlowError>(format!("value-of-{tenant}-{resource}").into_bytes())
        }
    })
    .map_err(refused)?;
    let report = host.run(&work, ()).await;
    if report.disposition().is_success() {
        report.into_result().map_err(refused)
    } else {
        Err(CacheError::Refused)
    }
}

//! Reference solution — `aggregate`, OLD API (`lgwks_bot::rt`).
//!
//! The old primitive bounds concurrency but does not fail fast, so the author
//! must start work in bounded waves of four and stop between them. That extra
//! burden is the point of the comparison.

use std::time::Duration;

use ai_task_support::{FetchError, Fetcher};
use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(ids: Vec<u32>, fetch: Fetcher, deadline: Duration) -> Result<u64, SolveError> {
    let work = async move {
        let mut sum: u64 = 0;
        let mut next: usize = 0;
        while next < ids.len() {
            let end = (next + 4).min(ids.len());
            let futures: Vec<_> = ids[next..end]
                .iter()
                .map(|&id| {
                    let fetcher = fetch.clone();
                    async move { fetcher.fetch(id).await }
                })
                .collect();
            let results = join_all_bounded(4, futures).await;
            next = end;
            for result in results {
                sum = sum.saturating_add(result.map_err(|error| SolveError::Fetch { id: error.id() })?);
            }
        }
        Ok(sum)
    };
    match time::timeout(deadline, work).await {
        Ok(result) => result,
        Err(_) => Err(SolveError::Deadline),
    }
}

//! Reference solution — `durable-retry`, OLD API (hand-rolled record).
//!
//! The record is an ordinary file and the wait is an ordinary sleep loop: no
//! facade is needed for exactly-once when the oracle never applies
//! concurrently. What the facade would add — atomicity under concurrency —
//! the test conditions never exercise, which the file says plainly. The
//! comparison with the `futures` arm is the one line that matters: read the
//! record before appending, and a recovery reconciles instead of duplicating.

use std::path::PathBuf;
use std::time::Duration;

use ai_task_support::durable::{append_application, has_application, is_released};

pub use ai_task_support::durable::RecoverError; // old arm

/// Refuse with `Deadline`, naming the cause on the trace stream.
fn deadline(cause: impl std::fmt::Debug) -> RecoverError {
    ai_task_support::diagnostic(format_args!("durable-retry old arm refused: {cause:?}"));
    RecoverError::Deadline
}

/// Refuse with `Deadline` as the whole answer, naming the cause on the trace
/// stream. A `return Err(..)` names no cause; returning this names it.
fn err_deadline<T>(cause: impl std::fmt::Debug) -> Result<T, RecoverError> {
    ai_task_support::diagnostic(format_args!("durable-retry old arm deadline: {cause:?}"));
    Err(RecoverError::Deadline)
}

pub async fn solve(
    dir: PathBuf,
    name: String,
    bound: Duration,
) -> Result<String, RecoverError> {
    std::fs::create_dir_all(&dir).map_err(deadline)?;
    // Read before appending: a line already there means an earlier attempt
    // applied and died before answering, so this call reconciles.
    let fresh = !has_application(&dir, &name).map_err(deadline)?;
    if fresh {
        append_application(&dir, &name).map_err(deadline)?;
    }
    let status = if fresh {
        format!("applied:{name}")
    } else {
        format!("recovered:{name}")
    };
    let started = std::time::Instant::now();
    loop {
        if is_released(&dir) {
            return Ok(status);
        }
        if started.elapsed() > bound {
            return err_deadline("the release never appeared in time");
        }
        lgwks_bot::rt::time::sleep(Duration::from_millis(10)).await;
    }
}

//! Reference solution — `pipeline`, OLD API (`lgwks_bot::rt`).
//!
//! The two fetches run concurrently through `join_all_bounded`; the error wave
//! is inspected in input order so a failure names its stage; `timeout` carries
//! the deadline and drops the whole pipeline when it expires.

use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageError, StageName};
use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

async fn run_stage(stage: Stage, name: StageName) -> Result<Artifact, PipelineError> {
    stage
        .run(name)
        .await
        .map_err(|error| match error {
            StageError::Stage { name } => PipelineError::Stage { name },
        })
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let work = async move {
        let names = [StageName::FetchA, StageName::FetchB];
        let futures: Vec<_> = names
            .into_iter()
            .map(|name| {
                let stage = stage.clone();
                async move { run_stage(stage, name).await }
            })
            .collect();
        let fetched = join_all_bounded(2, futures).await;
        for result in fetched {
            result?;
        }
        let _combined = run_stage(stage.clone(), StageName::Combine).await?;
        let published = run_stage(stage, StageName::Publish).await?;
        Ok(Published::from(published))
    };
    match time::timeout(deadline, work).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

//! Reference solution — `tenant-cache`, OLD API (hand-rolled correctly).
//!
//! Without a facade the author holds the two invariants by hand: the map key
//! carries the tenant, and the token is compared before anything is read or
//! stored. Correct, and the comparison with the `new` arm is exactly the cost
//! of holding both by hand on every call — one missed check away from the
//! `futures` arm's leak.

use std::collections::HashMap;
use std::sync::{Mutex, OnceLock};

/// This task's refusal type.
pub use ai_task_support::tenant_cache::CacheError;

/// One entry per tenant per resource: the tenant is part of the key, so one
/// tenant's bytes are unreachable from another's by construction.
fn entries() -> &'static Mutex<HashMap<(String, String), Vec<u8>>> {
    static CACHED: OnceLock<Mutex<HashMap<(String, String), Vec<u8>>>> = OnceLock::new();
    CACHED.get_or_init(|| Mutex::new(HashMap::new()))
}

/// Whether `token` opens `tenant`'s reads and nothing else.
fn allowed(tenant: &str, token: &str) -> bool {
    token == format!("token-for-{tenant}")
}

/// Refuse the read as the whole answer, naming why on the trace stream.
/// A `return Err(..)` names no cause; returning this names it.
fn err_refused<T>(cause: impl std::fmt::Debug) -> Result<T, CacheError> {
    ai_task_support::diagnostic(format_args!("tenant-cache old arm refused: {cause:?}"));
    Err(CacheError::Refused)
}

pub async fn solve(tenant: &str, resource: &str, token: &str) -> Result<Vec<u8>, CacheError> {
    if !allowed(tenant, token) {
        return err_refused("the token does not open this tenant");
    }
    let mut held = match entries().lock() {
        Ok(guard) => guard,
        Err(poisoned) => poisoned.into_inner(),
    };
    let slot = (tenant.to_owned(), resource.to_owned());
    if let Some(found) = held.get(&slot) {
        return Ok(found.clone());
    }
    let value = format!("value-of-{tenant}-{resource}").into_bytes();
    held.insert(slot, value.clone());
    Ok(value)
}

//! Reference solution — `aggregate`, SCRIPT arm (the `script!` language).
//!
//! The fan-out is a flow: `each` bounded by a named width, with the first
//! failure recorded into a cell the flow takes as an argument. The plain
//! `solve` keeps the deadline, the tenant and the error mapping; the flow
//! keeps the orchestration. A `record_first_failure` helper holds the only
//! lock, so the flow body stays straight-line Rust with no branching past one
//! `if`.

use std::sync::{Arc, Mutex};
use std::time::Duration;

/// The error type this task resolves.
pub use ai_task_support::aggregate::SolveError as SolveError;
use ai_task_support::Fetcher;
use lgwks_bot::script::{FlowError, Scope, Tenant, within};

/// Remember the first id whose fetch failed, ignoring every later one.
///
/// Whole-value assignment under the lock: the cell holds `None` or one id, so
/// a panic elsewhere cannot leave it half-written, and taking the poisoned
/// guard's value keeps the failure the run actually saw first.
fn record_first_failure(failed: &Mutex<Option<u32>>, id: u32) {
    let mut guard = match failed.lock() {
        Ok(guard) => guard,
        Err(poisoned) => poisoned.into_inner(),
    };
    if guard.is_none() {
        *guard = Some(id);
    }
}

lgwks_bot::script! {
    /// Fetch every id, four at a time, and sum the values.
    flow gather(
        ids: Vec<u32>,
        fetch: ai_task_support::Fetcher,
        failed: std::sync::Arc<std::sync::Mutex<Option<u32>>>,
        width: usize,
    ) -> u64:
        let partials = each id in ids, at most (width) at once:
            let outcome = fetch.fetch(id).await
            if outcome.is_err():
                record_first_failure(&failed, id)
                fail with "fetch failed"
            outcome.or_fail()?
        give back partials.into_iter().sum()
}

/// The caller's cancellation, naming the cause on the trace stream.
fn cancelled(cause: impl std::fmt::Debug) -> SolveError {
    ai_task_support::diagnostic(format_args!("aggregate script arm cancelled: {cause:?}"));
    SolveError::Cancelled
}

/// Refuse with `Deadline` as the whole answer, naming the cause on the trace
/// stream. A `return Err(..)` names no cause; returning this names it.
fn err_deadline<T>(cause: impl std::fmt::Debug) -> Result<T, SolveError> {
    ai_task_support::diagnostic(format_args!("aggregate script arm deadline: {cause:?}"));
    Err(SolveError::Deadline)
}

/// Refuse with `Cancelled` as the whole answer, naming the cause on the trace
/// stream. A `return Err(..)` names no cause; returning this names it.
fn err_cancelled<T>(cause: impl std::fmt::Debug) -> Result<T, SolveError> {
    ai_task_support::diagnostic(format_args!("aggregate script arm: already cancelled: {cause:?}"));
    Err(SolveError::Cancelled)
}

pub async fn solve(ids: Vec<u32>, fetch: Fetcher, deadline: Duration) -> Result<u64, SolveError> {
    let tenant = Tenant::new("aggregate").map_err(cancelled)?;
    let outer = Scope::root(tenant);
    let inner = outer.clone();
    let failed: Arc<Mutex<Option<u32>>> = Arc::new(Mutex::new(None));
    let failed_for_outcome = Arc::clone(&failed);
    let outcome = within(&outer, "deadline", deadline, async move {
        gather(&inner, ids, fetch, failed, 4).await
    })
    .await;
    if let Err(FlowError::TimedOut { .. }) = outcome {
        return err_deadline("the deadline scope timed out");
    }
    if let Err(FlowError::Cancelled { .. }) = outcome {
        return err_cancelled("the deadline scope was cancelled");
    }
    if outcome.is_ok() {
        return outcome.map_err(cancelled);
    }
    match failed_for_outcome.lock() {
        Ok(guard) => match *guard {
            Some(id) => Err(SolveError::Fetch { id }),
            None => Err(SolveError::Cancelled),
        },
        Err(poisoned) => match *poisoned.into_inner() {
            Some(id) => Err(SolveError::Fetch { id }),
            None => Err(SolveError::Cancelled),
        },
    }
}

//! Reference solution — `capture`, SCRIPT arm (the `script!` language).
//!
//! The flow owns the run the way the `new` reference does, written as a flow:
//! a `step` scope around the supervised run, `fail with` for the two ways a
//! run never settles, and the outcome as data the plain `solve` maps onto the
//! task's errors. The `spawn:` / `cancelled` reason markers are this file's
//! own convention for carrying the run's verdict through `FlowError::Failed`,
//! which is the only error a flow returns.

use std::num::NonZeroUsize;
use std::time::Duration;

/// Re-exported task vocabulary for the oracle.
pub use ai_task_support::capture::CaptureResult;
/// Re-exported task error for the oracle.
pub use ai_task_support::capture::CaptureError;
use lgwks_bot::rt::process::{ProcessRunError, ProcessSpec};
use lgwks_bot::rt::supervise::Supervisor;
use lgwks_bot::script::{FlowError, Scope, Tenant};

/// Refuse a spawn, naming why on the trace stream.
fn spawn(note: &str) -> CaptureError {
    ai_task_support::diagnostic(format_args!("capture script arm: spawn refused: {note}"));
    CaptureError::Spawn(note.to_owned())
}

/// Refuse with `Deadline` as the whole answer, naming the cause on the trace
/// stream. A `return Err(..)` names no cause; returning this names it.
fn err_deadline<T>(cause: impl std::fmt::Debug) -> Result<T, CaptureError> {
    ai_task_support::diagnostic(format_args!("capture script arm deadline: {cause:?}"));
    Err(CaptureError::Deadline)
}

lgwks_bot::script! {
    /// Run one command under supervision and hand back its outcome.
    flow supervised(
        program: String,
        args: Vec<String>,
        head_limit: usize,
        deadline: Duration,
    ) -> (Vec<u8>, u64, bool, bool):
        let limit = NonZeroUsize::new(head_limit).ok_or("zero head_limit").or_fail()?
        let mut detail = ProcessSpec::new(program)
        for arg in args:
            detail.arg(arg)
        detail.capture_stdout(limit)
        detail.capture_stderr(limit)
        detail.deadline(deadline)
        let mut owned = Supervisor::new(1)
        let outcome = owned.run_process(&detail).await
        if matches!(outcome, Err(ProcessRunError::NotStarted { .. })):
            fail with "spawn: the program did not start"
        if outcome.is_err():
            fail with "cancelled: stopped while running"
        let finished = outcome.or_fail()?
        let kept = finished.stdout()
        give back (
            kept.bytes().to_vec(),
            kept.total_bytes(),
            kept.truncated(),
            finished.deadline_fired(),
        )
}

pub async fn solve(
    argv: Vec<String>,
    head_limit: usize,
    deadline: Duration,
) -> Result<CaptureResult, CaptureError> {
    let (program, args) = argv
        .split_first()
        .map(|(first, rest)| (first.clone(), rest.to_vec()))
        .ok_or_else(|| spawn("empty argv"))?;
    let tenant = Tenant::new("capture").map_err(|error| CaptureError::Spawn(error.to_string()))?;
    let scope = Scope::root(tenant);
    match supervised(&scope, program, args, head_limit, deadline).await {
        Ok((head, total, truncated, fired)) => {
            if fired {
                return err_deadline("the run outlived its deadline");
            }
            Ok(CaptureResult::new(head, total, truncated))
        }
        Err(FlowError::Failed { reason, .. }) if reason.starts_with("spawn:") => {
            Err(CaptureError::Spawn(reason))
        }
        Err(FlowError::Failed { .. }) => Err(CaptureError::Cancelled),
        Err(FlowError::TimedOut { .. }) => Err(CaptureError::Deadline),
        Err(other) => Err(CaptureError::Spawn(other.to_string())),
    }
}

//! Reference solution — `durable-retry`, SCRIPT arm (the `script!` language).
//!
//! The record discipline is plain Rust — read before appending, exactly one
//! line per key — and the wait is a flow: a `retry` block that returns the
//! status the moment the release file exists, fails the deadline the moment
//! it passes, and otherwise waits transiently. The flow never returns
//! `Unknown`: a missing release is a wait, never a verdict.

use std::path::PathBuf;
use std::time::Duration;

use lgwks_bot::script::{FlowError, Scope, Tenant};

pub use ai_task_support::durable::RecoverError; // script arm

/// Refuse with `Deadline`, naming the cause on the trace stream.
fn deadline(cause: impl std::fmt::Debug) -> RecoverError {
    ai_task_support::diagnostic(format_args!("durable-retry script arm refused: {cause:?}"));
    RecoverError::Deadline
}

lgwks_bot::script! {
    /// Wait for the release file, then hand back the settled status.
    flow await_release(dir: PathBuf, status: String, deadline: Duration) -> String:
        let started = std::time::Instant::now()
        for _attempt in 0..1000u32:
            if started.elapsed() > deadline:
                fail with "deadline"
            if std::path::Path::new(&dir.join("release")).exists():
                give back status
            lgwks_bot::rt::time::sleep(std::time::Duration::from_millis(100)).await
        fail with "release never appeared"
}

pub async fn solve(
    home: PathBuf,
    job: String,
    span: Duration,
) -> Result<String, RecoverError> {
    use ai_task_support::durable::{append_application, has_application};
    std::fs::create_dir_all(&home).map_err(deadline)?;
    let settled_before = has_application(&home, &job).map_err(deadline)?;
    if !settled_before {
        append_application(&home, &job).map_err(deadline)?;
    }
    let status = if settled_before {
        format!("recovered:{job}")
    } else {
        format!("applied:{job}")
    };
    let scope = Scope::root(Tenant::new("durable").map_err(deadline)?);
    match await_release(&scope, home, status, span).await {
        Ok(done) => Ok(done),
        Err(FlowError::Failed { reason, .. }) if reason == "deadline" => {
            Err(RecoverError::Deadline)
        }
        Err(FlowError::Exhausted { .. }) | Err(FlowError::TimedOut { .. }) => {
            Err(RecoverError::Deadline)
        }
        Err(_) => Err(RecoverError::Unknown),
    }
}

//! Reference solution — `pipeline`, SCRIPT arm (the `script!` language).
//!
//! The fetch pair is a flow: `together` runs both fetches concurrently and the
//! first failure stops the sibling, then `combine` and `publish` run in turn.
//! A shared cell records which stage failed first; the plain `solve` keeps the
//! tenant, the deadline and the error mapping, reading the cell only when the
//! flow itself cannot name the failure.

use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::{Published, Stage, StageName};
use lgwks_bot::script::{FlowError, Scope, Tenant, within};

/// The task's fixed stage error.
pub use ai_task_support::pipeline::PipelineError;

/// Remember the stage that failed first, leaving a recorded stage alone.
///
/// Whole-value assignment under the lock: the cell holds `None` or one name,
/// so a panic elsewhere cannot leave it half-written.
fn record_stage(failed: &Mutex<Option<StageName>>, name: StageName) {
    let mut guard = match failed.lock() {
        Ok(guard) => guard,
        Err(poisoned) => poisoned.into_inner(),
    };
    if guard.is_none() {
        *guard = Some(name);
    }
}

/// Read the recorded stage, defaulting to cancellation when none failed.
///
/// A separate function rather than an inline match: the flow cannot name a
/// failure that never reached a stage, and blaming `FetchA` for the flow's
/// own error would indict a stage that ran and succeeded.
fn recorded_or_cancelled(failed: &Mutex<Option<StageName>>) -> PipelineError {
    match failed.lock() {
        Ok(guard) => match *guard {
            Some(name) => PipelineError::Stage { name },
            None => PipelineError::Cancelled,
        },
        Err(poisoned) => match *poisoned.into_inner() {
            Some(name) => PipelineError::Stage { name },
            None => PipelineError::Cancelled,
        },
    }
}

lgwks_bot::script! {
    /// Run one stage, recording its name when it fails.
    flow fetch_single(
        stage: ai_task_support::Stage,
        name: ai_task_support::StageName,
        failed: std::sync::Arc<std::sync::Mutex<Option<ai_task_support::StageName>>>,
    ) -> u64:
        let outcome = stage.run(name).await
        if outcome.is_err():
            record_stage(&failed, name)
            fail with "stage failed"
        give back outcome.or_fail()?.value()

    /// Run both fetches concurrently; the first failure stops the sibling.
    flow fetch_both(
        stage: ai_task_support::Stage,
        failed: std::sync::Arc<std::sync::Mutex<Option<ai_task_support::StageName>>>,
    ) -> (u64, u64):
        let other = stage.clone()
        let failed_a = failed.clone()
        together:
            let a = run fetch_single(stage, ai_task_support::StageName::FetchA, failed_a)
            let b = run fetch_single(other, ai_task_support::StageName::FetchB, failed)
        give back (a, b)

    /// Fetch, combine and publish in order.
    flow run_pipeline(
        stage: ai_task_support::Stage,
        failed: std::sync::Arc<std::sync::Mutex<Option<ai_task_support::StageName>>>,
    ) -> ai_task_support::Published:
        let worker = stage.clone()
        let failed_later = failed.clone()
        let _fetched = run fetch_both(worker, failed)
        let combined_outcome = stage.run(ai_task_support::StageName::Combine).await
        if combined_outcome.is_err():
            record_stage(&failed_later, ai_task_support::StageName::Combine)
            fail with "combine failed"
        let combined = combined_outcome.or_fail()?
        let published_outcome = stage.run(ai_task_support::StageName::Publish).await
        if published_outcome.is_err():
            record_stage(&failed_later, ai_task_support::StageName::Publish)
            fail with "publish failed"
        give back ai_task_support::Published::from(published_outcome.or_fail()?)
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let tenant = Tenant::new("pipeline").map_err(|error| {
        ai_task_support::diagnostic(format_args!("pipeline script arm: tenant refused: {error:?}"));
        PipelineError::Cancelled
    })?;
    let outer = Scope::root(tenant);
    let failed: Arc<Mutex<Option<StageName>>> = Arc::new(Mutex::new(None));
    let failed_for_outcome = Arc::clone(&failed);
    let inner = outer.clone();
    let outcome = within(&outer, "deadline", deadline, async move {
        run_pipeline(&inner, stage, failed).await
    })
    .await;
    match outcome {
        Ok(published) => Ok(published),
        Err(FlowError::TimedOut { .. }) => Err(PipelineError::Deadline),
        Err(FlowError::Cancelled { .. }) => Err(PipelineError::Cancelled),
        Err(_) => Err(recorded_or_cancelled(&failed_for_outcome)),
    }
}

//! Reference solution — `recovery`, SCRIPT arm (the `script!` language).
//!
//! The units loop is a flow: `for` over the world's width, each unit awaited
//! in turn, the first failure returning early with its index. The effect
//! applies once by reading the ledger before applying, in plain Rust beside
//! the flow. The plain `recover` keeps the derived run identity, the host and
//! the run-then-resume orchestration; the flow keeps the per-unit work.
//!
//! Two deliberate differences from the `new` arm, both load-bearing. The
//! failure index travels in the flow's own outcome enum rather than a shared
//! `Option` cell, and the "no failure recorded" sentinel is `u32::MAX`
//! rather than `None`: a second spelling of the same contract, so a defect in
//! one spelling shows up as a divergence rather than a shared blind spot.

use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use ai_task_support::recovery::{Ledger, World};
use lgwks_bot::effect::RunId;
use lgwks_bot::script::Scope;
use lgwks_bot::task::{Disposition, Host, task};

/// The task's fixed recovery error.
pub use ai_task_support::recovery::RecoveryError;

/// The tenant every recovered run is booked under.
const TENANT: &str = "recovery";

/// The effect name the ledger is asked to apply exactly once.
const EFFECT: &str = "recover";

/// The run identity, derived rather than minted.
///
/// Any stable non-zero 32-hex value works: both attempts derive the same run
/// so the second finds the first attempt's records. A freshly minted identity
/// per call would derive a different run every time and the resume would find
/// nothing.
const RUN: &str = "7e4b1c90d2f848632a7e5b4c9d1f3a01";

/// Which unit failed, or that none has: `u32::MAX` means no failure recorded.
type FailedUnit = Arc<Mutex<u32>>;

/// Note the first unit that failed, leaving a recorded failure alone.
fn note_failure(failed: &Mutex<u32>, index: u32) {
    let mut guard = match failed.lock() {
        Ok(guard) => guard,
        Err(poisoned) => poisoned.into_inner(),
    };
    if *guard == u32::MAX {
        *guard = index;
    }
}

/// Refuse with `NoStore` as the whole answer, naming the cause on the trace
/// stream. A `return Err(..)` names no cause; returning this names it.
fn err_no_store<T>(cause: impl std::fmt::Debug) -> Result<T, RecoveryError> {
    ai_task_support::diagnostic(format_args!("recovery script arm: no store: {cause:?}"));
    Err(RecoveryError::NoStore)
}

/// Refuse with `Deadline` as the whole answer, naming the cause on the trace
/// stream. A `return Err(..)` names no cause; returning this names it.
fn err_deadline<T>(cause: impl std::fmt::Debug) -> Result<T, RecoveryError> {
    ai_task_support::diagnostic(format_args!("recovery script arm deadline: {cause:?}"));
    Err(RecoveryError::Deadline)
}

lgwks_bot::script! {
    /// Run every unit in turn, stopping at the first failure.
    flow work_units(world: ai_task_support::recovery::World, failed: std::sync::Arc<std::sync::Mutex<u32>>) -> u64:
        let mut total = 0u64
        for index in 0..world.width():
            let outcome = world.unit(&scope, index).await
            if outcome.is_err():
                note_failure(&failed, index)
                fail with "unit failed"
            total = total.saturating_add(outcome.or_fail()?)
        let ledger = world.ledger().clone()
        if !ledger.applied("recover"):
            ledger.apply("recover")
        give back total
}

/// Read one attempt's outcome into the caller's error type.
fn settled(report: &lgwks_bot::task::Report<u64>, failed: &FailedUnit) -> Result<u64, RecoveryError> {
    if report.disposition().is_success() {
        return report.output().copied().ok_or(RecoveryError::NoLedger);
    }
    if report.disposition() == Disposition::DeadlineExceeded {
        return err_deadline("deadline exceeded");
    }
    let recorded = match failed.lock() {
        Ok(guard) => *guard,
        Err(poisoned) => *poisoned.into_inner(),
    };
    if recorded == u32::MAX {
        return err_no_store("no failure recorded");
    }
    Err(RecoveryError::Unit { index: recorded })
}

pub async fn recover(
    world: World,
    store_dir: PathBuf,
    deadline: Duration,
) -> Result<u64, RecoveryError> {
    let run = RunId::from_hex(RUN).map_err(|error| {
        ai_task_support::diagnostic(format_args!("recovery script arm: run identity refused: {error:?}"));
        RecoveryError::NoStore
    })?;
    let host = Host::builder(TENANT)
        .map_err(|error| {
            ai_task_support::diagnostic(format_args!("recovery script arm: tenant refused: {error:?}"));
            RecoveryError::NoStore
        })?
        .default_deadline(deadline)
        .run_store(&store_dir)
        .map_err(|error| {
            ai_task_support::diagnostic(format_args!("recovery script arm: run store refused: {error:?}"));
            RecoveryError::NoStore
        })?
        .build()
        .map_err(|error| {
            ai_task_support::diagnostic(format_args!("recovery script arm: host build refused: {error:?}"));
            RecoveryError::NoStore
        })?;
    let failed: FailedUnit = Arc::new(Mutex::new(u32::MAX));
    let failed_for_settled = Arc::clone(&failed);
    let work = task("flow-units", move |scope: Scope, _attempt: u32| {
        let world = world.clone();
        let failed = Arc::clone(&failed);
        async move { work_units(&scope, world, failed).await }
    })
    .map_err(|error| {
        ai_task_support::diagnostic(format_args!("recovery script arm: task refused: {error:?}"));
        RecoveryError::NoStore
    })?;

    // The first attempt. Whatever it reaches, its records are already on the
    // disk, so the resume below can find them.
    let first = host.run(&work, 0u32).await;
    let done = settled(&first, &failed_for_settled);
    if done.is_ok() {
        return done;
    }

    // The second attempt, under the same derived run: recorded units replay
    // without their bodies running again, and the units the first attempt did
    // not reach run now.
    let resumed = host.resume(run, &work, 0u32).await;
    settled(&resumed, &failed_for_settled)
}

//! Reference solution — `tenant-cache`, SCRIPT arm (the `script!` language).
//!
//! Authority still lives in the host's grants, but the read itself is a flow:
//! a `step` scope around the require and the value, called from a thin task
//! body. The flow is where an author would hang more steps — audit, fallback,
//! fan-out — without touching the admission boundary around it.

/// The task's refusal, aliased so the oracle resolves it.
pub use ai_task_support::tenant_cache::CacheError as CacheError;
use lgwks_bot::gate::GrantSet;
use lgwks_bot::script::Scope;
use lgwks_bot::task::{Host, task};

lgwks_bot::script! {
    /// Read one tenant's value under the run's authority.
    flow serve_value(tenant: String, resource: String) -> Vec<u8>:
        step authorised:
            scope.require(&[lgwks_bot::cap::Cap::new("cache.read")])?
            format!("value-of-{tenant}-{resource}").into_bytes()
}

/// Refuse the read, naming the failed step on the trace stream.
fn refused(cause: impl std::fmt::Debug) -> CacheError {
    ai_task_support::diagnostic(format_args!("tenant-cache script arm refused: {cause:?}"));
    CacheError::Refused
}

pub async fn solve(tenant: &str, resource: &str, token: &str) -> Result<Vec<u8>, CacheError> {
    // The token buys the cache capability for the tenant's own token and
    // nothing otherwise; the decision is inline because this arm keeps the
    // whole admission where the host is built.
    let admitted = if token == format!("token-for-{tenant}") {
        GrantSet::empty().grant(lgwks_bot::cap::Cap::new("cache.read"))
    } else {
        GrantSet::empty()
    };
    let host = Host::builder(tenant)
        .map_err(refused)?
        .grants(admitted)
        .build()
        .map_err(refused)?;
    let owned_tenant = tenant.to_owned();
    let owned_resource = resource.to_owned();
    let work = task("serve", move |scope: Scope, _: ()| {
        let owned_tenant = owned_tenant.clone();
        let owned_resource = owned_resource.clone();
        async move { serve_value(&scope, owned_tenant, owned_resource).await }
    })
    .map_err(refused)?;
    // Any non-success — Blocked, Failed, Cancelled — is a refusal: the value
    // is only readable under the run's authority.
    host.run(&work, ()).await.into_result().map_err(refused)
}
